def compute(vars):
    value_thousand = vars["v1"]
    value_millions = value_thousand / 1000
    return {
        "value": value_millions,
        "trace": {
            "value_thousand": value_thousand,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": None
            }
        }
    }
